/**
 * Recognizes the numeric interval filters generated by Studio.
 * @param {Array} filter GeoStyler filter.
 * @returns {string|undefined} Classified field, or undefined for other filters.
 */
const getIntervalField = (filter) => {
  if (
    Array.isArray(filter) &&
    filter.length === 3 &&
    filter[0] === "&&" &&
    [">", ">="].includes(filter[1]?.[0]) &&
    filter[2]?.[0] === "<=" &&
    filter[1][1] === filter[2][1]
  ) {
    return filter[1][1];
  }
};

/**
 * Separates complete size/color classifications into two legend groups.
 * Other styles retain their original rules. Map filters and symbols are unchanged.
 * @param {Object[]} rules Graphic GeoStyler rules.
 * @returns {Object[]} Legend rules, including headings for combined classifications.
 */
export const getLegendRules = (rules) => {
  if (!rules.length) return rules;
  const sizeField = getIntervalField(rules[0].filter?.[1]);
  const firstColorFilter = rules[0].filter?.[2];
  const colorField =
    firstColorFilter?.[0] === "=="
      ? firstColorFilter[1]
      : getIntervalField(firstColorFilter);
  if (!sizeField || !colorField || sizeField === colorField) return rules;

  const sizes = new Map();
  const colors = new Map();
  const combinations = new Set();
  for (const rule of rules) {
    const [symbol] = rule.symbolizers;
    const filter = rule.filter;
    const separator = rule.name?.indexOf(" / ");
    if (
      rule.symbolizers.length !== 1 ||
      symbol.kind !== "Mark" ||
      symbol.wellKnownName !== "circle" ||
      !Number.isFinite(symbol.radius) ||
      filter?.[0] !== "&&" ||
      filter.length !== 3 ||
      getIntervalField(filter[1]) !== sizeField ||
      separator === undefined ||
      separator < 0
    ) {
      return rules;
    }
    const colorFilter = filter[2];
    const field =
      colorFilter?.[0] === "==" ? colorFilter[1] : getIntervalField(colorFilter);
    if (field !== colorField) return rules;

    const sizeKey = JSON.stringify(filter[1]);
    const colorKey = JSON.stringify(colorFilter);
    const combination = JSON.stringify([sizeKey, colorKey]);
    const sizeName = rule.name.slice(0, separator);
    const colorName = rule.name.slice(separator + 3);
    const { radius, ...colorSymbol } = symbol;
    if (
      combinations.has(combination) ||
      (sizes.has(sizeKey) &&
        (sizes.get(sizeKey).symbolizers[0].radius !== radius ||
          sizes.get(sizeKey).name !== sizeName)) ||
      (colors.has(colorKey) &&
        (JSON.stringify(colors.get(colorKey).symbolizers[0]) !==
          JSON.stringify({ ...colorSymbol, radius: 5 }) ||
          colors.get(colorKey).name !== colorName))
    ) {
      return rules;
    }
    combinations.add(combination);
    sizes.set(sizeKey, {
      name: sizeName,
      symbolizers: [{ ...symbol, color: "#808080", fillOpacity: 1 }],
    });
    colors.set(colorKey, {
      name: colorName,
      symbolizers: [{ ...colorSymbol, radius: 5 }],
    });
  }
  if (combinations.size !== sizes.size * colors.size) return rules;

  return [
    { name: sizeField, heading: true, symbolizers: [] },
    ...sizes.values(),
    { name: colorField, heading: true, symbolizers: [] },
    ...colors.values(),
  ];
};
